PrologProcedure:
# the opening balance period (WFP Period, Period Type 'Opening')
sObl = '';
nOP = 1;
WHILE( nOP <= DIMSIZ( 'WFP Period' ) );
   IF( ATTRS( 'WFP Period', DIMNM( 'WFP Period', nOP ), 'Period Type' ) @= 'Opening' ); sObl = DIMNM( 'WFP Period', nOP ); ENDIF;
   nOP = nOP + 1;
END;
IF( sObl @= '' ); ProcessQuit; ENDIF;
#Region WFP Generate Positions — demo-scale roster (simulated HRIS extract)
# Adds pCount generated positions (codes <prefix>-1001, -1002, …) on top of the
# hand-typed WFP Load Positions roster, which it leaves alone.
# Deterministic: a fixed-seed generator (LCG, exact in TM1 doubles) and exactly
# 12 draws per position, so the same pSeed gives the same people every run —
# re-running is idempotent, and a larger pCount only adds people.
# Shape: weighted cost centres; companies UK 45% / US 40% / NZ 15% (regional
# sales teams pinned); grade pyramid G1 30 / G2 35 / G3 22 / G4 10 / G5 3;
# salary inside the WFP Pay Rates band; 7% part-time; 8% contractors;
# 92% filled, 4% open reqs, 4% to-be-hired.
# Existing staff get Start Period 2025-12 (on the books before the plan window)
# so January 2026 opens with real headcount; ~12% joined Jan–Mar 2026.
cDim = 'WFP Position';
cPR  = 'WFP Pay Rates';
cPer = 'WFP Period';
nSeed = pSeed;
nLcgA = 9301; nLcgC = 49297; nLcgM = 233280;

# cost centre ; department ; job family ; code prefix ; weight ; company (* = spread)
vCCs =
'CC-ENG-PLT;Engineering;Engineering;ENG;150;*~' |
'CC-ENG-APP;Engineering;Engineering;ENG;170;*~' |
'CC-ENG-DATA;Engineering;Engineering;ENG;110;*~' |
'CC-ENG-MOB;Engineering;Engineering;ENG;90;*~' |
'CC-ENG-SEC;Engineering;Engineering;ENG;45;*~' |
'CC-ENG-QA;Engineering;Engineering;ENG;70;*~' |
'CC-ENG-SRE;Engineering;Engineering;ENG;65;*~' |
'CC-ENG-ML;Engineering;Engineering;ENG;55;*~' |
'CC-ENG-INT;Engineering;Engineering;ENG;60;*~' |
'CC-PROD;Product;Product;PRD;70;*~' |
'CC-DESIGN;Product;Product;PRD;45;*~' |
'CC-RESEARCH;Product;Product;PRD;25;*~' |
'CC-PROD-ANL;Product;Product;PRD;30;*~' |
'CC-SALES;Sales;Sales;SLS;60;*~' |
'CC-SALES-UK;Sales;Sales;SLS;110;UK Ltd~' |
'CC-SALES-NA;Sales;Sales;SLS;140;US Inc~' |
'CC-SALES-APAC;Sales;Sales;SLS;55;NZ Ltd~' |
'CC-SALES-ENT;Sales;Sales;SLS;70;*~' |
'CC-PARTNER;Sales;Sales;SLS;30;*~' |
'CC-SDR;Sales;Sales;SLS;95;*~' |
'CC-SALESOPS;Sales Ops;Sales;SOP;40;*~' |
'CC-MKT;Marketing;Marketing;MKT;30;*~' |
'CC-MKT-DEM;Marketing;Marketing;MKT;55;*~' |
'CC-MKT-PRD;Marketing;Marketing;MKT;40;*~' |
'CC-MKT-BRAND;Marketing;Marketing;MKT;30;*~' |
'CC-CS;Customer Success;Customer Success;CS;110;*~' |
'CC-CS-ONB;Customer Success;Customer Success;CS;70;*~' |
'CC-CS-SUP;Customer Success;Customer Success;CS;160;*~' |
'CC-CS-SVC;Customer Success;Customer Success;CS;80;*~' |
'CC-FIN;Finance;Finance;FIN;20;*~' |
'CC-FIN-FPA;Finance;Finance;FIN;25;*~' |
'CC-FIN-ACC;Finance;Finance;FIN;40;*~' |
'CC-LEGAL;Legal;Admin;LEG;25;*~' |
'CC-PPL;People;People;PPL;30;*~' |
'CC-PPL-TA;People;People;PPL;35;*~' |
'CC-PPL-LD;People;People;PPL;15;*~' |
'CC-ITOPS;IT & Ops;IT;ITO;45;*~' |
'CC-ITOPS-SEC;IT & Ops;IT;ITO;20;*~' |
'CC-FAC;IT & Ops;Admin;ITO;30;*~' |
'CC-EXEC;Executive;Leadership;EXEC;12;*~';

vFirst = 'Aisha|Ben|Chloe|Daniel|Elena|Felix|Grace|Hiro|Isla|James|Kavya|Liam|Maya|Noah|Olivia|Pita|Quinn|Ravi|Sofia|Tom|Uma|Victor|Wen|Xavier|Yara|Zane|Amara|Bruno|Carmen|Dev|Emma|Finn|Gabriel|Hana|Ivan|Jade|Kai|Lucia|Mateo|Nina|';
vLast  = 'Ahmed|Brown|Chen|Davies|Evans|Fernandez|Garcia|Hughes|Ito|Jones|Kaur|Lopez|Martin|Ngata|O''Brien|Patel|Quinn|Roberts|Singh|Taylor|Ueda|Vasquez|Walker|Xu|Young|Zhang|Anderson|Baker|Clarke|Diaz|Edwards|Fox|Green|Hall|Iqbal|Johnson|Kim|Lee|Moore|Nguyen|';

# total weight
nW = 0; vL = vCCs;
WHILE( SCAN( '~', vL ) > 1 );
   nS = SCAN( '~', vL ); vRec = SUBST( vL, 1, nS - 1 ); vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
   vT = vRec; nK = 1;
   WHILE( nK <= 4 ); vT = SUBST( vT, SCAN( ';', vT ) + 1, LONG( vT ) ); nK = nK + 1; END;
   nW = nW + NUMBR( SUBST( vT, 1, SCAN( ';', vT ) - 1 ) );
END;

# Legal is a new department under G&A
IF( DIMIX( cDim, 'Legal' ) = 0 );
   DimensionElementInsertDirect( cDim, '', 'Legal', 'C' );
ENDIF;
IF( ELISANC( cDim, 'G&A', 'Legal' ) = 0 );
   DimensionElementComponentAddDirect( cDim, 'G&A', 'Legal', 1 );
ENDIF;

nMade = 0;
nI = 1;
WHILE( nI <= pCount );
   # ---- 12 draws, always, so position i is the same whatever pCount is ----
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR1 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR2 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR3 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR4 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR5 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR6 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR7 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR8 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR9 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR10 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR11 = nSeed / nLcgM;
   nX = nSeed * nLcgA + nLcgC; nSeed = nX - INT( nX / nLcgM ) * nLcgM; nR12 = nSeed / nLcgM;

   # ---- cost centre (weighted) ----
   nPick = nR1 * nW; nAcc = 0; vL = vCCs; vCC = '';
   WHILE( SCAN( '~', vL ) > 1 & vCC @= '' );
      nS = SCAN( '~', vL ); vRec = SUBST( vL, 1, nS - 1 ) | ';'; vL = SUBST( vL, nS + 1, LONG( vL ) - nS );
      nS = SCAN( ';', vRec ); vC1 = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
      nS = SCAN( ';', vRec ); vC2 = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
      nS = SCAN( ';', vRec ); vC3 = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
      nS = SCAN( ';', vRec ); vC4 = SUBST( vRec, 1, nS - 1 ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
      nS = SCAN( ';', vRec ); nC5 = NUMBR( SUBST( vRec, 1, nS - 1 ) ); vRec = SUBST( vRec, nS + 1, LONG( vRec ) - nS );
      nS = SCAN( ';', vRec ); vC6 = SUBST( vRec, 1, nS - 1 );
      nAcc = nAcc + nC5;
      IF( nPick < nAcc % SCAN( '~', vL ) = 0 );
         vCC = vC1; vDept = vC2; vJob = vC3; vPrefix = vC4; vEntPin = vC6;
      ENDIF;
   END;

   # ---- company + location ----
   IF( vEntPin @<> '*' );
      vEntity = vEntPin;
   ELSEIF( nR2 < 0.45 );
      vEntity = 'UK Ltd';
   ELSEIF( nR2 < 0.85 );
      vEntity = 'US Inc';
   ELSE;
      vEntity = 'NZ Ltd';
   ENDIF;
   vLoc    = IF( vEntity @= 'UK Ltd', 'London', IF( vEntity @= 'US Inc', 'New York', 'Auckland' ) );
   vSalCur = IF( vLoc @= 'London', 'GBP', IF( vLoc @= 'New York', 'USD', 'NZD' ) );
   vTaxJur = IF( vLoc @= 'London', 'UK', IF( vLoc @= 'New York', 'US-NY', 'NZ' ) );

   # ---- grade (pyramid; executives senior) ----
   IF( vDept @= 'Executive' );
      vGrade = IF( nR3 < 0.6, 'G4', 'G5' );
   ELSE;
      vGrade = IF( nR3 < 0.30, 'G1', IF( nR3 < 0.65, 'G2', IF( nR3 < 0.87, 'G3', IF( nR3 < 0.97, 'G4', 'G5' ) ) ) );
   ENDIF;

   # ---- status, FTE, employment type ----
   vStatus  = IF( nR4 < 0.92, 'Filled', IF( nR4 < 0.96, 'Open Req', 'TBH' ) );
   nFTE     = IF( nR5 < 0.93, 1, IF( nR5 < 0.96, 0.8, IF( nR5 < 0.98, 0.6, 0.5 ) ) );
   vEmpType = IF( nR6 < 0.92, 'Permanent', 'Contractor' );

   # ---- dates ----
   vEndPd = ''; nEndDay = 0; nStartDay = 1;
   IF( vStatus @= 'Filled' );
      IF( nR7 < 0.88 );
         vStartPd = sObl;
      ELSE;
         vStartPd = '2026-0' | NUMBERTOSTRING( 1 + INT( nR8 * 3 ) );
         nStartDay = 1 + INT( nR9 * 28 );
      ENDIF;
      # half the contractors are on fixed terms ending Jun 2026 .. Dec 2027
      IF( vEmpType @= 'Contractor' & nR10 < 0.5 );
         nEndIdx = 18 + INT( nR11 * 19 );
         nY = IF( nEndIdx <= 24, 2026, 2027 ); nM = nEndIdx - ( nY - 2025 ) * 12;
         vEndPd = NUMBERTOSTRING( nY ) | '-' | IF( nM < 10, '0', '' ) | NUMBERTOSTRING( nM );
         nEndDay = ATTRN( cPer, vEndPd, 'Days In Month' );
      ENDIF;
   ELSEIF( vStatus @= 'Open Req' );
      # target start Apr .. Dec 2026
      nM = 4 + INT( nR8 * 9 );
      vStartPd = '2026-' | IF( nM < 10, '0', '' ) | NUMBERTOSTRING( nM );
   ELSE;
      vStartPd = '2026-01';
   ENDIF;

   # ---- salary inside the pay band ----
   nMin = CellGetN( cPR, '2026-01', 'Budget', vGrade, vJob, vLoc, 'Salary Min' );
   nMax = CellGetN( cPR, '2026-01', 'Budget', vGrade, vJob, vLoc, 'Salary Max' );
   nSal = IF( vStatus @= 'Filled', ROUNDP( ( nMin + nR12 * ( nMax - nMin ) ) / 500, 0 ) * 500, 0 );

   # ---- name (filled only) ----
   vInc = '';
   IF( vStatus @= 'Filled' );
      nK = 1 + INT( nR9 * 40 ); vT = vFirst;
      WHILE( nK > 1 ); vT = SUBST( vT, SCAN( '|', vT ) + 1, LONG( vT ) ); nK = nK - 1; END;
      vInc = SUBST( vT, 1, SCAN( '|', vT ) - 1 );
      nK = 1 + INT( nR10 * 40 ); vT = vLast;
      WHILE( nK > 1 ); vT = SUBST( vT, SCAN( '|', vT ) + 1, LONG( vT ) ); nK = nK - 1; END;
      vInc = vInc | ' ' | SUBST( vT, 1, SCAN( '|', vT ) - 1 );
   ENDIF;

   vCode = vPrefix | '-' | NUMBERTOSTRING( 1000 + nI );

   IF( DIMIX( 'WFP Cost Centre', vCC ) = 0 % DIMIX( 'WFP Job Family', vJob ) = 0 );
      ASCIIOUTPUT( 'WFP_Generate_Positions_rejects.txt', vCode, vCC, vJob );
   ELSE;
      IF( DIMIX( cDim, vCode ) = 0 );
         DimensionElementInsertDirect( cDim, '', vCode, 'N' );
      ENDIF;
      IF( ELISANC( cDim, vDept, vCode ) = 0 );
         DimensionElementComponentAddDirect( cDim, vDept, vCode, 1 );
      ENDIF;
      AttrPutS( vDept,    cDim, vCode, 'Department' );
      AttrPutS( vCC,      cDim, vCode, 'Cost Centre' );
      AttrPutS( vLoc,     cDim, vCode, 'Location' );
      AttrPutS( vGrade,   cDim, vCode, 'Grade' );
      AttrPutS( vJob,     cDim, vCode, 'Job Family' );
      AttrPutN( nFTE,     cDim, vCode, 'FTE' );
      AttrPutS( vStatus,  cDim, vCode, 'Position Status' );
      AttrPutS( vStartPd, cDim, vCode, 'Start Period' );
      AttrPutN( nStartDay, cDim, vCode, 'Start Day' );
      AttrPutS( vEndPd,   cDim, vCode, 'End Period' );
      AttrPutN( nEndDay,  cDim, vCode, 'End Day' );
      AttrPutS( vInc,     cDim, vCode, 'Incumbent Name' );
      AttrPutN( nSal,     cDim, vCode, 'Seed Base Salary' );
      AttrPutS( vEntity,  cDim, vCode, 'Home Entity' );
      AttrPutS( vEmpType, cDim, vCode, 'Employment Type' );
      AttrPutS( vSalCur,  cDim, vCode, 'Salary Currency' );
      AttrPutS( vTaxJur,  cDim, vCode, 'Tax Jurisdiction' );
      nMade = nMade + 1;
   ENDIF;
   nI = nI + 1;
END;
ASCIIOUTPUT( 'WFP_Generate_Positions_ok.txt', 'Generated ' | NUMBERTOSTRING( nMade ) | ' positions (seed ' | NUMBERTOSTRING( pSeed ) | ')' );
#EndRegion
